import{_ as d,o as e,c as a,a2 as s}from"./chunks/framework.DTdEDYjJ.js";const E=JSON.parse('{"title":"错误与恢复","description":"","frontmatter":{},"headers":[],"relativePath":"reference/errors.md","filePath":"reference/errors.md"}'),r={name:"reference/errors.md"};function i(o,t,h,n,l,p){return e(),a("div",null,[...t[0]||(t[0]=[s(`<h1 id="错误与恢复" tabindex="-1">错误与恢复 <a class="header-anchor" href="#错误与恢复" aria-label="Permalink to &quot;错误与恢复&quot;">​</a></h1><p>先区分连接失败、认证失败、执行状态冲突和任务结果不确定。不要把一次 HTTP 重试直接变成一次新任务。</p><h2 id="错误格式" tabindex="-1">错误格式 <a class="header-anchor" href="#错误格式" aria-label="Permalink to &quot;错误格式&quot;">​</a></h2><p>节点通常返回：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;ok&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;message&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;描述错误的文本&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;code&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;OPTIONAL_MACHINE_CODE&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><code>code</code> 是可选字段。普通认证错误、非法 JSON 或连接在请求体超限时被关闭，不保证都有完整 JSON 回执。客户端要同时处理 HTTP 状态、JSON 和网络错误。</p><h2 id="http-状态" tabindex="-1">HTTP 状态 <a class="header-anchor" href="#http-状态" aria-label="Permalink to &quot;HTTP 状态&quot;">​</a></h2><table tabindex="0"><thead><tr><th>状态</th><th>常见原因</th><th>建议</th></tr></thead><tbody><tr><td>400</td><td>参数、任务模式或 URL 不符合要求</td><td>修正请求，不重复提交同一非法请求</td></tr><tr><td>401</td><td>缺少或使用了错误的节点令牌</td><td>核对目标节点与凭据，不把模型 Key 当作节点令牌</td></tr><tr><td>404</td><td>Bot、任务或接口不存在</td><td>核对稳定 ID 与实际节点版本</td></tr><tr><td>409</td><td>执行会话、屏幕代次或请求 ID 冲突</td><td>获取新状态，按具体冲突恢复</td></tr><tr><td>410</td><td>任务历史已归档</td><td>查看记录，不将同一请求当作新任务重跑</td></tr><tr><td>413</td><td>请求体超过2 MB</td><td>缩小请求；连接也可能被关闭</td></tr><tr><td>429</td><td>默认每 IP 每分钟240次的限制</td><td>降低查询频率，避免无界轮询</td></tr><tr><td>503</td><td>执行未启用、已关闭或持久存储不可用</td><td>修复节点能力或存储，再核对任务状态</td></tr></tbody></table><h2 id="执行协议错误" tabindex="-1">执行协议错误 <a class="header-anchor" href="#执行协议错误" aria-label="Permalink to &quot;执行协议错误&quot;">​</a></h2><table tabindex="0"><thead><tr><th>code</th><th>含义与恢复方向</th></tr></thead><tbody><tr><td><code>EXECUTION_UNAVAILABLE</code></td><td>节点未启用浏览器执行，检查启动参数与实际能力</td></tr><tr><td><code>EXECUTION_SESSION_REQUIRED</code></td><td>当前没有有效控制会话，显式连接</td></tr><tr><td><code>EXECUTION_SESSION_BUSY</code></td><td>另一客户端持有控制会话，不能抢占式重试</td></tr><tr><td><code>STALE_SCREEN</code></td><td>画面目标或输入序号已过期，重新获取画面</td></tr><tr><td><code>SCREEN_NOT_TAKEN_OVER</code></td><td>当前操作要求人工先接管该屏幕</td></tr><tr><td><code>REQUEST_ID_CONFLICT</code></td><td>同一请求 ID 被用于不同任务内容，应人工核对</td></tr><tr><td><code>API_EXECUTION_CHANGED</code></td><td>排队或提交后执行配置已变化，不能静默套用新配置</td></tr><tr><td><code>APPROVAL_EXPIRED</code></td><td>当时的授权已失效，旧回执不能恢复权限</td></tr><tr><td><code>APPROVAL_SESSION_MISMATCH</code></td><td>审批不属于当前会话</td></tr><tr><td><code>TASK_ARCHIVED</code></td><td>持久历史已归档，不重新派发副作用</td></tr><tr><td><code>EXECUTION_STORAGE_UNAVAILABLE</code></td><td>持久化失败，先修复存储</td></tr></tbody></table><p>具体错误以对应版本源码为准；内部执行协议没有独立的稳定 SDK 承诺。</p><h2 id="浏览器打不开" tabindex="-1">浏览器打不开 <a class="header-anchor" href="#浏览器打不开" aria-label="Permalink to &quot;浏览器打不开&quot;">​</a></h2><p>确认 Chromium 路径、执行用户、沙箱配置和可写数据目录。Docker 教程使用固定浏览器版本及专属资料目录；不要加入 <code>--no-sandbox</code> 来掩盖环境错误。</p><p>容器崩溃会留下 Chromium 单实例链接。现有入口脚本先取得整个运行期持有的排他锁，再清理三个瞬时链接，保留 Cookie 和浏览器资料。不要在浏览器运行中手动删锁，也不要绕过入口共享数据目录。</p><h2 id="断线后的任务不确定" tabindex="-1">断线后的任务不确定 <a class="header-anchor" href="#断线后的任务不确定" aria-label="Permalink to &quot;断线后的任务不确定&quot;">​</a></h2><p>先恢复连接并查询持久任务。<code>requestId</code>、节点身份与原任务归属需要保持一致；不得因为响应丢失就生成新 ID 重派。</p><p>离线取消会在重连时对账。已经发生的操作不会因取消或回滚代码而自动撤销；先检查页面、动作记录与结果，再决定是否开始新任务。</p><h2 id="启动成功但模型不可用" tabindex="-1">启动成功但模型不可用 <a class="header-anchor" href="#启动成功但模型不可用" aria-label="Permalink to &quot;启动成功但模型不可用&quot;">​</a></h2><p><code>ping</code>、Docker healthcheck 和模型健康检测是不同层次。节点可达不代表模型凭据有效，也不代表所选模型支持截图或工具。</p><p>健康检测会使用少量模型额度。排查时先核对保存的模型、连接和 Harness；不要用自动付费循环不断重跑同一失败。</p><p>相关文档：<a href="/openbot/reference/node-api.html">Node API</a> · <a href="/openbot/deployment/network.html">连接与网络</a> · <a href="/openbot/guide/models.html">模型接入</a>。</p>`,21)])])}const k=d(r,[["render",i]]);export{E as __pageData,k as default};
